using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using NonBaoHiemVietTin.Data; using NonBaoHiemVietTin.Models;
namespace NonBaoHiemVietTin.Controllers; public sealed class SubscribeController(AppDbContext db):Controller { [HttpPost] public async Task<IActionResult> News(Subscribe sub){if(string.IsNullOrWhiteSpace(sub.Email))return Json(new{status=-1,message="Email không hợp lệ."});if(await db.Subscribes.AnyAsync(x=>x.Email==sub.Email))return Json(new{status=0,message="Email này đã đăng kí nhận tin rồi!!"});db.Subscribes.Add(sub);await db.SaveChangesAsync();return Json(new{status=1,message="Chúc mừng bạn đã đăng kí thành công!!"});} }
